package id.putusan.dashboard.ui;

import id.putusan.dashboard.util.PdfExtractor;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.nio.file.Path;
public class ImportPanel extends JPanel {
 public ImportPanel(){setLayout(new BorderLayout(0,16));setBackground(UiStyle.BG);setBorder(new EmptyBorder(24,28,24,28));JLabel title=new JLabel("Import Dokumen PDF");title.setFont(new Font("SansSerif",Font.BOLD,25));JLabel sub=UiStyle.muted("Ekstrak text layer dari putusan untuk ditinjau sebelum pemrosesan lanjutan.");JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.add(title);h.add(Box.createVerticalStrut(5));h.add(sub);add(h,BorderLayout.NORTH);
  JPanel card=UiStyle.card();card.setLayout(new BorderLayout(0,14));JPanel top=new JPanel(new BorderLayout(12,0));top.setOpaque(false);JLabel info=new JLabel("Pilih file PDF untuk memulai ekstraksi.");info.setForeground(UiStyle.MUTED);JButton pick=UiStyle.primary("Pilih file PDF  ↑");top.add(info,BorderLayout.CENTER);top.add(pick,BorderLayout.EAST);JTextArea preview=new JTextArea();preview.setEditable(false);preview.setFont(new Font("Monospaced",Font.PLAIN,12));preview.setLineWrap(true);preview.setWrapStyleWord(true);preview.setText("Pratinjau hasil ekstraksi akan muncul di sini.\n\nCatatan: PDF hasil scan mungkin memerlukan OCR. Aplikasi tidak akan menebak nilai yang tidak terbaca.");card.add(top,BorderLayout.NORTH);card.add(new JScrollPane(preview),BorderLayout.CENTER);add(card,BorderLayout.CENTER);
  pick.addActionListener(e->{JFileChooser c=new JFileChooser();c.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("PDF documents (*.pdf)","pdf"));if(c.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){Path path=c.getSelectedFile().toPath();preview.setText("Sedang mengekstrak dokumen...");pick.setEnabled(false);new SwingWorker<PdfExtractor.Extraction,Void>(){protected PdfExtractor.Extraction doInBackground()throws Exception{return new PdfExtractor().extract(path);}protected void done(){pick.setEnabled(true);try{var x=get();preview.setText("FILE       : "+x.sourceFile()+"\nHALAMAN   : "+x.pages()+"\nTEXT LAYER: "+(x.hasText()?"Tersedia":"Tidak tersedia")+"\n\n────────────────────────────────────────\n\n"+(x.hasText()?x.text():"PDF tidak memiliki text layer. OCR diperlukan; tidak ada data yang ditebak."));preview.setCaretPosition(0);}catch(Exception ex){preview.setText("Ekstraksi gagal: "+ex.getMessage());}}}.execute();}});
 }
}
